messages.text:
{include("Novelcrafter/Personas")}

{! Codex entries that matter for this beat !}
{include("Novelcrafter/Codex")}

{! Summaries of all scenes before this one !}
{#if storySoFar}
  The story so far:
  {storySoFar}
{#endif}

{! Sent as the AI's own words, so the model keeps the style of the text. !}

{! At the start of a scene: the end of the previous scene, if it has the same POV character !}
{#if and(
  isStartOfText,
  pov.character is pov.character(scene.previous)
)}
  {lastWords(scene.fullText(scene.previous), 650)}
{#endif}

{! Otherwise: the text before the beat !}
{textBefore}

Write {input("Words")} words that continue the story, following these instructions:
<instructions>
  {! Point of view of the novel, or of this scene !}
  {pov}

  {message}
</instructions>

{include("Novelcrafter/AdditionalContext")}
